const raw = $input.first().json.body || $input.first().json || {};

const studentName = (raw.student_name || raw.fullName || raw.name || 'GTF Kandidat').trim();
const email = (raw.email || raw.userEmail || 'demo@gatewaytofuture.com').toLowerCase().trim();
const rawPhone = String(raw.whatsapp_phone || raw.phone || '+4915228372894');
const whatsappPhoneE164 = rawPhone.replace(/[^0-9]/g, '');
const productTitle = (raw.product_title || raw.productTitle || 'GTF B1 Intensiv Prüfungs-Pack').trim();
const productSlug = (raw.product_slug || raw.productSlug || 'b1-pro-pack-5').trim();
const accessLink = (raw.access_link || raw.accessLink || `https://app.gatewaytofuture.com/dashboard?email=${encodeURIComponent(email)}&pack=${encodeURIComponent(productSlug)}`).trim();
const loginPassword = raw.login_password || `GTF-${ email.split('@')[0].slice(0, 6).toUpperCase() }-2026`;
const paymentProvider = raw.payment_provider || raw.paymentProvider || 'razorpay_stripe_checkout';
const paymentReference = raw.payment_reference || raw.paymentReference || `GTF-TXN-${Date.now()}`;
const currency = (raw.currency || 'INR').toUpperCase();
const amountPaid = raw.amount_paid ?? raw.amountPaid ?? 0;
const timestampIso = new Date().toISOString();

const whatsappBody = `Guten Tag ${studentName}! 🇩🇪\n\nAapka *${productTitle}* ab Gateway To Future (GTF) Exam Portal par officially active ho chuka hai.\n\n🔐 *Aapke Portal Login Credentials:*\n• *Portal URL:* https://app.gatewaytofuture.com/dashboard\n• *Registered Email:* ${email}\n• *Access Passcode:* ${loginPassword}\n• *Direct Pack Link:* ${accessLink}\n\n📌 *Important Exam Instructions (Berlin HQ Standard):*\n1. *Hören Module:* Goethe aur telc ke official rules ke hisaab se audio sirf 1x ya 2x play hoga — headphones pehen kar शांत माहौल mein attempt karein.\n2. *Schreiben & Sprechen AI:* Apna ईमेल/पत्र likhne aur आवाज़ record karne ke baad turant CEFR score aur line-by-line German + Hinglish correction check karein.\n3. *PDF Workbooks:* Right-panel interactive answer sheet mein apne answers save karein.\n\nAgar aapko کسی bhi module ya Germany relocation/visa process mein guidance chahiye, toh seedha is official Berlin number (+49 1522 8372894) par apna registered email bhej dein.\n\nViel Erfolg bei der Prüfungsvorbereitung!\n*Sarbjit Kour (Founder & CEO, Gateway To Future)*\n*The Gateway to Future (GTF) — Schönefelder Straße 2, GStU, 12355 Berlin*\nhttps://www.gatewaytofuture.com`;

return [
  {
    json: {
      timestamp_iso: timestampIso,
      student_name: studentName,
      email,
      whatsapp_phone: rawPhone,
      whatsapp_phone_clean: whatsappPhoneE164,
      product_title: productTitle,
      product_slug: productSlug,
      access_link: accessLink,
      login_password: loginPassword,
      payment_provider: paymentProvider,
      payment_reference: paymentReference,
      currency,
      amount_paid: amountPaid,
      whatsapp_message_text: whatsappBody,
      crm_stage: 'PACK_UNLOCKED_ACTIVE'
    }
  }
];

